"""Canonical workflow node for assigning relevant embedded DOCX images."""

from __future__ import annotations

import logging
from typing import Any

from langchain_core.runnables import RunnableConfig

from backend.workflows.slidegen_workflow.graph.stage import State

logger = logging.getLogger(__name__)


def _assignment_instruction(assignments: list[dict[str, Any]]) -> str:
    lines = [
        "Verified source-image guidance (generated by the multimodal reviewer):",
        "Use a verified source image only on the listed slide and only when the selected XML layout has a compatible image slot. Do not invent a different image subject.",
    ]
    for assignment in assignments:
        slide_number = int(assignment.get("slide_index", 0)) + 1
        lines.append(
            f"- Slide {slide_number}: source image {assignment.get('image_id', '')}; "
            f"role={assignment.get('role', 'illustration')}; "
            f"document section={assignment.get('section_path', '')[:240]}."
        )
    return "\n".join(lines)


def verify_document_images(state: State, config: RunnableConfig) -> State:
    """Review DOCX images against canonical slide chunks before planning.

    This node is deliberately optional.  Extraction and storage happen during
    document ingestion; only a generation request has enough slide context for
    Qwen-VL to make a meaningful placement decision.
    """
    print("\n---------------- Executing Node: image_verifier ----------------")
    options = dict(state.get("slide_options") or {})
    images = list(state.get("document_images") or options.get("document_images") or [])
    verifier = (config or {}).get("configurable", {}).get("image_relevance_verifier")
    stream_callback = (config or {}).get("configurable", {}).get("stream_callback")
    if images and verifier is not None and stream_callback:
        stream_callback(
            "status",
            {
                "stage": "image_verification",
                "title": "Checking source visuals",
                "description": "Matching embedded document images with the planned slide content...",
                "message": "Checking source visuals",
            },
        )
    if not images or verifier is None:
        state["document_image_assignments"] = []
        options["document_image_assignments"] = []
        state["slide_options"] = options
        return state

    slide_chunks = list(state.get("slide_chunks") or [])
    if not slide_chunks:
        state["document_image_assignments"] = []
        options["document_image_assignments"] = []
        state["slide_options"] = options
        return state

    try:
        assignments = verifier.assign_document_images(
            images=images,
            slide_chunks=slide_chunks,
            user_request=str(
                state.get("user_request") or options.get("user_request") or ""
            ),
        )
    except Exception:
        logger.exception("Document image verification node failed")
        assignments = []

    state["document_image_assignments"] = assignments
    options["document_image_assignments"] = assignments
    if assignments:
        existing = str(options.get("presentation_instruction") or "").strip()
        guidance = _assignment_instruction(assignments)
        options["presentation_instruction"] = (
            f"{existing}\n\n{guidance}" if existing else guidance
        )
        print(f"  -> Verified {len(assignments)} document image placement(s)")
    else:
        print("  -> No document image was approved for the generated deck")
    state["slide_options"] = options
    return state
